using JTradeERP.Application.Common.Exceptions;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Features.Billing.NumberSeries.Common;using MediatR;namespace JTradeERP.Application.Features.Billing.NumberSeries.GetNumberSeriesById;public sealed class GetNumberSeriesByIdHandler(IApplicationDbContext db):IRequestHandler<GetNumberSeriesByIdQuery,GetNumberSeriesByIdResponse>{public Task<GetNumberSeriesByIdResponse> Handle(GetNumberSeriesByIdQuery r,CancellationToken ct){var x=db.NumberSeries.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Number series not found.");return Task.FromResult(new GetNumberSeriesByIdResponse(new(x.Id,x.DocumentType,x.Prefix,x.NextNumber,x.Padding)));}}
